    public function fetch_currencies($params = array ()): ?array {
        /**
         * fetches all available $currencies on the exchange
         *
         * @see https://api.dreamdex.io/v0/.well-known/oapi.json
         *
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} an associative dictionary of $currencies
         */
        $response = $this->publicGetV0Currencies ($params);
        //
        //     {
        //         "currencies" => array(
        //             array( "id" => "0x28f34...", "code" => "SOMI", "name" => "Somnia Token", "decimals" => 18 ),
        //             array( "id" => "0x00000...", "code" => "USDso", "name" => "USD Somnia", "decimals" => 18 )
        //         )
        //     }
        //
        $currencies = $this->safe_list($response, 'currencies', array());
        $result = array();
        for ($i = 0; $i < count($currencies); $i++) {
            $currency = $currencies[$i];
            $id = $this->safe_string($currency, 'code');
            $code = $this->safe_currency_code($id);
            $name = $this->safe_string($currency, 'name');
            $decimals = $this->safe_integer($currency, 'decimals');
            $precision = null;
            if ($decimals !== null) {
                $precision = $this->parse_number($this->parse_precision($this->number_to_string($decimals)));
            }
            $result[$code] = $this->safe_currency_structure(array(
                'id' => $id,
                'code' => $code,
                'name' => $name,
                'type' => 'crypto',
                'active' => true,
                'deposit' => true,
                'withdraw' => true,
                'fee' => null,
                'precision' => $precision,
                'limits' => array(
                    'deposit' => array(
                        'min' => null,
                        'max' => null,
                    ),
                    'withdraw' => array(
                        'min' => null,
                        'max' => null,
                    ),
                ),
                'networks' => array(),
                'info' => $currency,
            ));
        }
        return $result;
    }

