    public function parse_market(array $market): array {
        $id = $this->safe_string($market, 'symbol');
        // $symbol is "BASE:QUOTE" using exchange currency codes (e.g. "SOMI:USDso")
        // $market->base/quote hold on-chain token contract addresses (is_array(info) && array_key_exists(preserved, info))
        // info.contract holds the pool/market contract address
        $parts = explode(':', $id);
        $baseId = $this->safe_string($parts, 0);
        $quoteId = $this->safe_string($parts, 1);
        $base = $this->safe_currency_code($baseId);
        $quote = $this->safe_currency_code($quoteId);
        $symbol = $base . '/' . $quote;
        return array(
            'id' => $id,
            'symbol' => $symbol,
            'base' => $base,
            'quote' => $quote,
            'settle' => null,
            'baseId' => $baseId,
            'quoteId' => $quoteId,
            'settleId' => null,
            'type' => 'spot',
            'spot' => true,
            'margin' => false,
            'swap' => false,
            'future' => false,
            'option' => false,
            'active' => true,
            'contract' => false,
            'linear' => null,
            'inverse' => null,
            'taker' => $this->parse_number('0'),
            'maker' => $this->parse_number('0'),
            'contractSize' => null,
            'expiry' => null,
            'expiryDatetime' => null,
            'strike' => null,
            'optionType' => null,
            'precision' => array(
                'amount' => $this->safe_number($market, 'lotSize', $this->parse_number($this->parse_precision($this->safe_string($market, 'baseDecimals')))),
                'price' => $this->safe_number($market, 'tickSize', $this->parse_number($this->parse_precision($this->safe_string($market, 'quoteDecimals')))),
            ),
            'limits' => array(
                'leverage' => array(
                    'min' => null,
                    'max' => null,
                ),
                'amount' => array(
                    'min' => $this->safe_number($market, 'minQuantity'),
                    'max' => null,
                ),
                'price' => array(
                    'min' => null,
                    'max' => null,
                ),
                'cost' => array(
                    'min' => null,
                    'max' => null,
                ),
            ),
            'created' => null,
            'info' => $market,
        );
    }

    public function fetch_order_book(string $symbol, ?int $limit = null, $params = array ()): array {
        /**
         * fetches information on open orders with bid (buy) and ask (sell) prices, volumes and other $data
         *
         * @see https://api.dreamdex.io/v0/.well-known/oapi.json
         *
         * @param {string} $symbol unified $market $symbol
         * @param {int} [$limit] the maximum amount of order book entries to return
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} A dictionary of ~@link https://docs.ccxt.com/#/?id=order-book-structure order book structures~ indexed by $market symbols
         */
        $this->load_markets();
        $market = $this->market($symbol);
        $request = array(
            'symbols' => $market['id'],
        );
        if ($limit !== null) {
            $request['depth'] = $limit;
        }
        $response = $this->publicGetV0Orderbooks ($this->extend($request, $params));
        //
        //     {
        //         "orderbooks" => array(
        //             {
        //                 "symbol" => "SOMI:USDso",
        //                 "timestamp" => 1765534169841,
        //                 "bids" => array( array( "price" => "1.24", "quantity" => "500" ) ),
        //                 "asks" => array( array( "price" => "1.26", "quantity" => "300" ) ),
        //                 "nonce" => 42
        //             }
        //         )
        //     }
        //
        $orderbooks = $this->safe_list($response, 'orderbooks', array());
        $data = $this->safe_dict($orderbooks, 0, array());
        $timestamp = $this->safe_integer($data, 'timestamp');
        $orderbook = $this->parse_order_book($data, $symbol, $timestamp, 'bids', 'asks', 'price', 'quantity');
        $orderbook['nonce'] = $this->safe_integer($data, 'nonce');
        return $orderbook;
    }

    public function fetch_ticker(string $symbol, $params = array ()): array {
        /**
         * fetches a price $ticker, a statistical calculation with the information for a specific $market
         *
         * @see https://api.dreamdex.io/v0/.well-known/oapi.json
         *
         * @param {string} $symbol unified $market $symbol
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} a ~@link https://docs.ccxt.com/#/?id=$ticker-structure $ticker structure~
         */
        $this->load_markets();
        $market = $this->market($symbol);
        $request = array(
            'symbol' => $market['id'],
        );
        $response = $this->publicGetV0MarketsSymbolTickers ($this->extend($request, $params));
        //
        //     {
        //         "symbols" => array(
        //             array( "symbol" => "SOMI:USDso", "timestamp" => 1765534169841, "open" => "1.20", "high" => "1.30", "low" => "1.18", "close" => "1.25", "volume" => "1000" )
        //         )
        //     }
        //
        $symbols = $this->safe_list($response, 'symbols', array());
        $ticker = $this->safe_dict($symbols, 0, array());
        return $this->parse_ticker($ticker, $market);
    }

    public function fetch_tickers(?array $symbols = null, $params = array ()): array {
        /**
         * fetches price $tickers for multiple markets
         *
         * @see https://api.dreamdex.io/v0/.well-known/oapi.json
         *
         * @param {string[]|null} [$symbols] unified $market $symbols to fetch $tickers for, all $tickers are returned if not specified
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} a dictionary of ~@link https://docs.ccxt.com/#/?id=ticker-structure ticker structures~
         */
        $this->load_markets();
        $request = array();
        if ($symbols !== null) {
            $marketIds = array();
            for ($i = 0; $i < count($symbols); $i++) {
                $market = $this->market($symbols[$i]);
                $marketIds[] = $market['id'];
            }
            $request['symbols'] = implode(',', $marketIds);
        }
        $response = $this->publicGetV0Tickers ($this->extend($request, $params));
        //
        //     {
        //         "symbols" => array(
        //             array( "symbol" => "SOMI:USDso", "timestamp" => 1765534169841, "open" => "1.20", "high" => "1.30", "low" => "1.18", "close" => "1.25", "volume" => "1000" )
        //         )
        //     }
        //
        $tickers = $this->safe_list($response, 'symbols', array());
        return $this->parse_tickers($tickers, $symbols);
    }

    public function parse_ticker(array $ticker, ?array $market = null): array {
        $marketId = $this->safe_string($ticker, 'symbol');
        $market = $this->safe_market($marketId, $market, ':');
        $timestamp = $this->safe_integer($ticker, 'timestamp');
        $close = $this->safe_string($ticker, 'close');
        return $this->safe_ticker(array(
            'symbol' => $market['symbol'],
            'timestamp' => $timestamp,
            'datetime' => $this->iso8601($timestamp),
            'high' => $this->safe_string($ticker, 'high'),
            'low' => $this->safe_string($ticker, 'low'),
            'bid' => null,
            'bidVolume' => null,
            'ask' => null,
            'askVolume' => null,
            'vwap' => null,
            'open' => $this->safe_string($ticker, 'open'),
            'close' => $close,
            'last' => $close,
            'previousClose' => null,
            'change' => null,
            'percentage' => null,
            'average' => null,
            'baseVolume' => $this->safe_string($ticker, 'volume'),
            'quoteVolume' => null,
            'info' => $ticker,
        ), $market);
    }

    public function fetch_trades(string $symbol, ?int $since = null, ?int $limit = null, $params = array ()): array {
        /**
         * get the list of most recent $trades for a particular $symbol
         *
         * @see https://api.dreamdex.io/v0/.well-known/oapi.json
         *
         * @param {string} $symbol unified $market $symbol
         * @param {int} [$since] timestamp in ms of the earliest trade to fetch
