        //             array( "id" => "t1", "timestamp" => 1765534169841, "symbol" => "SOMI:USDso", "side" => "buy", "price" => "1.25", "amount" => "100", "cost" => "125" )
        //         )
        //     }
        //
        $trades = $this->safe_list($response, 'trades', array());
        return $this->parse_trades($trades, $market, $since, $limit);
    }

    public function fetch_my_trades(?string $symbol = null, ?int $since = null, ?int $limit = null, $params = array ()): array {
        /**
         * fetch all $trades made by the user
         *
         * @see https://api.dreamdex.io/v0/.well-known/oapi.json
         *
         * @param {string} $symbol unified $market $symbol, required for dreamdex
         * @param {int} [$since] timestamp in ms of the earliest trade to fetch
         * @param {int} [$limit] the maximum number of $trades to fetch
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {Trade[]} a list of ~@link https://docs.ccxt.com/#/?id=trade-structure trade structures~
         */
        if ($symbol === null) {
            throw new ArgumentsRequired($this->id . ' fetchMyTrades() requires a $symbol argument');
        }
        $this->authenticate_rest();
        $this->load_markets();
        $market = $this->market($symbol);
        $request = array(
            'symbol' => $market['id'],
        );
        if ($since !== null) {
            $request['since'] = $since;
        }
        if ($limit !== null) {
            $request['limit'] = $limit;
        }
        $response = $this->privateGetV0MarketsSymbolTradesMine ($this->extend($request, $params));
        //
        //     {
        //         "symbol" => "SOMI:USDso",
        //         "trades" => array(
        //             array( "id" => "123:456", "timestamp" => 1765534169841, "symbol" => "SOMI:USDso", "side" => "buy", "price" => "1.25", "amount" => "100", "cost" => "125" )
        //         )
        //     }
        //
        $trades = $this->safe_list($response, 'trades', array());
        return $this->parse_trades($trades, $market, $since, $limit);
    }

    public function parse_trade(array $trade, ?array $market = null): array {
        $marketId = $this->safe_string($trade, 'symbol');
        $market = $this->safe_market($marketId, $market, ':');
        $timestamp = $this->safe_integer($trade, 'timestamp');
        return $this->safe_trade(array(
            'id' => $this->safe_string($trade, 'id'),
            'info' => $trade,
            'timestamp' => $timestamp,
            'datetime' => $this->iso8601($timestamp),
            'symbol' => $market['symbol'],
            'order' => null,
            'type' => null,
            'side' => $this->safe_string($trade, 'side'),
            'takerOrMaker' => null,
            'price' => $this->safe_string($trade, 'price'),
            'amount' => $this->safe_string($trade, 'amount'),
            'cost' => $this->safe_string($trade, 'cost'),
            'fee' => null,
        ), $market);
    }

    public function fetch_ohlcv(string $symbol, string $timeframe = '1m', ?int $since = null, ?int $limit = null, $params = array ()): array {
        /**
         * fetches historical candlestick data containing the open, high, low, close price, and the volume of a $market
         *
         * @see https://api.dreamdex.io/v0/.well-known/oapi.json
         *
         * @param {string} $symbol unified $market $symbol
         * @param {string} [$timeframe] the length of time each candle represents, default '1m'
         * @param {int} [$since] timestamp in ms of the earliest candle to fetch
         * @param {int} [$limit] the maximum number of $candles to fetch
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {int[][]} A list of $candles ordered, open, high, low, close, volume
         */
        $this->load_markets();
        $market = $this->market($symbol);
        $request = array(
            'symbol' => $market['id'],
            'interval' => $this->safe_string($this->timeframes, $timeframe, $timeframe),
        );
        if ($since !== null) {
            $request['since'] = $since;
        }
        if ($limit !== null) {
            $request['limit'] = $limit;
        }
        $response = $this->publicGetV0MarketsSymbolCandles ($this->extend($request, $params));
        //
        //     {
        //         "symbol" => "SOMI:USDso",
        //         "interval" => "1m",
        //         "candles" => array(
        //             array( "timestamp" => 1765534140000, "open" => "1.24", "high" => "1.26", "low" => "1.23", "close" => "1.25", "volume" => "1000" )
        //         )
        //     }
        //
        $candles = $this->safe_list($response, 'candles', array());
        return $this->parse_ohlcvs($candles, $market, $timeframe, $since, $limit);
    }

    public function parse_ohlcv($ohlcv, ?array $market = null): array {
        return array(
            $this->safe_integer($ohlcv, 'timestamp'),
            $this->safe_number($ohlcv, 'open'),
            $this->safe_number($ohlcv, 'high'),
            $this->safe_number($ohlcv, 'low'),
            $this->safe_number($ohlcv, 'close'),
            $this->safe_number($ohlcv, 'volume'),
        );
    }

    public function fetch_balance($params = array ()): array {
        /**
         * query for balance in a specific $market vault. DreamDEX uses per-$market vaults rather than a single exchange-wide wallet, so $params->symbol is required. The API does not distinguish between free and locked (in-order) $balances, so all balance is reported.
         *
         * @see https://api.dreamdex.io/v0/.well-known/oapi.json
         *
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} $params->symbol unified $market $symbol (required — vault is per-$market)
         * @return {array} a ~@link https://docs.ccxt.com/#/?id=balance-structure balance structure~
         */
        $this->authenticate_rest();
        $this->load_markets();
        $symbol = $this->safe_string($params, 'symbol');
        if ($symbol === null) {
            throw new ArgumentsRequired($this->id . ' fetchBalance() requires a $params->symbol argument (vault is per-$market)');
        }
        $market = $this->market($symbol);
        $request = array(
            'symbol' => $market['id'],
            'walletAddress' => $this->walletAddress,
        );
        $params = $this->omit($params, 'symbol');
        $response = $this->privateGetV0MarketsSymbolVaultBalance ($this->extend($request, $params));
        //
        //     {
        //         "balances" => array(
        //             array( "currency" => "SOMI", "amount" => "1000.5" ),
        //             array( "currency" => "USDso", "amount" => "500.25" )
        //         )
        //     }
        //
        $balances = $this->safe_list($response, 'balances', array());
        return $this->parse_balance($balances);
    }

    public function parse_balance($response): array {
        $result = array( 'info' => $response );
        for ($i = 0; $i < count($response); $i++) {
            $balance = $this->safe_dict($response, $i, array());
            $currencyId = $this->safe_string($balance, 'currency');
            $code = $this->safe_currency_code($currencyId);
            $account = $this->account();
            $total = $this->safe_string($balance, 'amount');
            $account['total'] = $total;
            $account['free'] = $total;
            $result[$code] = $account;
        }
        return $this->safe_balance($result);
    }

    public function vault_approve(string $symbol, string $currency, ?float $amount, $params = array ()): mixed {
        /**
         * generates an unsigned ERC-20 approve transaction, or returns null for native tokens
         *
         * @see https://api.dreamdex.io/v0/.well-known/oapi.json
         *
         * @param {string} $symbol unified market $symbol identifying the vault
         * @param {string} $currency currency code to approve (e.g. 'SOMI' or 'USDso')
         * @param {float} $amount the $amount to approve for spending
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->walletAddress] the wallet address (defaults to $this->walletAddress)
         * @return {array|null} an unsigned EVM transaction or null if no approval is required
         */
        return $this->vault_action('approve', $symbol, $currency, $amount, $params);
    }

    public function vault_deposit(string $symbol, string $currency, ?float $amount, $params = array ()): array {
        /**
         * generates an unsigned EVM transaction for depositing tokens into a per-market vault
         *
         * @see https://api.dreamdex.io/v0/.well-known/oapi.json
         *
         * @param {string} $symbol unified market $symbol identifying the vault
         * @param {string} $currency currency code to deposit (e.g. 'SOMI' or 'USDso')
         * @param {float} $amount the $amount to deposit
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->walletAddress] the wallet address (defaults to $this->walletAddress)
         * @return {array} an unsigned EVM transaction array( to, data, value, chainId, gasLimit, nonce )
         */
        return (await $this->vault_action('deposit', $symbol, $currency, $amount, $params));
    }

    public function vault_withdraw(string $symbol, string $currency, ?float $amount, $params = array ()): array {
        /**
         * generates an unsigned EVM transaction for withdrawing tokens from a per-market vault
         *
         * @see https://api.dreamdex.io/v0/.well-known/oapi.json
         *
         * @param {string} $symbol unified market $symbol identifying the vault
         * @param {string} $currency currency code to withdraw (e.g. 'SOMI' or 'USDso')
         * @param {float} $amount the $amount to withdraw
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->walletAddress] the wallet address (defaults to $this->walletAddress)
         * @return {array} an unsigned EVM transaction array( to, data, value, chainId, gasLimit, nonce )
         */
        return (await $this->vault_action('withdraw', $symbol, $currency, $amount, $params));
    }

    public function vault_action(string $action, string $symbol, string $currency, ?float $amount, $params = array ()): mixed {
        $this->authenticate_rest();
        $this->load_markets();
        $market = $this->market($symbol);
        $walletAddress = $this->safe_string($params, 'walletAddress', $this->walletAddress);
        $params = $this->omit($params, 'walletAddress');
        $currencyObj = $this->currency($currency);
        $request = array(
            'symbol' => $market['id'],
            'walletAddress' => $walletAddress,
            'currency' => $currencyObj['id'],
            'amount' => $this->number_to_string($amount),
        );
        $response = null;
        if ($action === 'approve') {
            $response = $this->privatePostV0MarketsSymbolVaultApprove ($this->extend($request, $params));
        } elseif ($action === 'deposit') {
            $response = $this->privatePostV0MarketsSymbolVaultDeposit ($this->extend($request, $params));
        } elseif ($action === 'withdraw') {
            $response = $this->privatePostV0MarketsSymbolVaultWithdraw ($this->extend($request, $params));
        }
        //
        //     {
        //         "to" => "0xcee4c19f4518A10FBeF92390FE6d9e7B18A4070c",
        //         "data" => "0x80702f83...",
        //         "value" => "0",
        //         "chainId" => "50312",
        //         "gasLimit" => "250000",
        //         "nonce" => "42"
        //     }
        //
        // The approve endpoint responds with JSON null when no approval is required
        // (e.g. native-token currencies). Normalize to null so callers can truthy-check.
        if ($response === null) {
            return null;
        }
        return $response;
    }

    public function create_order(string $symbol, string $type, string $side, float $amount, ?float $price = null, $params = array ()): array {
        /**
         * creates an order by returning an unsigned EVM transaction for the user to sign and broadcast on-chain.
         * The order is not placed until the transaction is submitted to the Somnia network (chain ID 50312).
         * The returned order structure has the unsigned transaction payload in the info field.
         *
         * @see https://api.dreamdex.io/v0/.well-known/oapi.json
         *
         * @param {string} $symbol unified $market $symbol
         * @param {string} $type 'limit' or 'market'
         * @param {string} $side 'buy' or 'sell'
         * @param {float} $amount how much of currency you want to trade in units of base currency
         * @param {float} [$price] the $price at which the order is to be fulfilled, in units of the quote currency, ignored in $market orders
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->walletAddress] the wallet address to place the order from (defaults to $this->walletAddress)
         * @param {float} [$params->triggerPrice] the $price at which a stop order is triggered - routes to the stop-orders endpoint
         * @param {float} [$params->stopPrice] alias for $triggerPrice
         * @param {string} [$params->triggerOperator] 'gte' or 'lte' - trigger condition (default => 'lte' for sell, 'gte' for buy)
         * @param {string} [$params->timeInForce] 'IOC', 'FOK', or 'PO' - maps to API orderType (immediateOrCancel, fillOrKill, $postOnly)
         * @param {bool} [$params->postOnly] true to create a post-only order (alternative to $timeInForce 'PO')
         * @param {string} [$params->fundingSource] 'wallet' or 'vault' - where to source tokens (default is 'wallet', 'vault' uses pre-deposited balance)
         * @param {string} [$params->selfMatchingOption] 'cancelTaker' or 'cancelMaker' - self-trade prevention behavior
         * @return {array} an ~@link https://docs.ccxt.com/#/?id=order-structure order structure~ with the unsigned EVM transaction in the info field
         */
        $this->authenticate_rest();
        $this->load_markets();
        $market = $this->market($symbol);
        $walletAddress = $this->safe_string($params, 'walletAddress', $this->walletAddress);
        $triggerPrice = $this->safe_string_2($params, 'triggerPrice', 'stopPrice');
        if ($triggerPrice !== null) {
            $triggerOperator = $this->safe_string($params, 'triggerOperator');
            if ($triggerOperator === null) {
                $triggerOperator = ($side === 'sell') ? 'lte' : 'gte';
            }
            $params = $this->omit($params, array( 'walletAddress', 'triggerPrice', 'stopPrice', 'triggerOperator' ));
            $isMarket = ($type === 'market');
            if (!$isMarket && $price === null) {
                throw new ArgumentsRequired($this->id . ' createOrder() requires a $price argument for stop limit orders');
            }
            $stopRequest = array(
                'symbol' => $market['id'],
                'walletAddress' => $walletAddress,
                'type' => $type,
                'side' => $side,
                'amount' => $this->amount_to_precision($symbol, $amount),
                'triggerPrice' => $this->price_to_precision($symbol, $triggerPrice),
                'triggerOperator' => $triggerOperator,
            );
            if (!$isMarket) {
                $stopRequest['price'] = $this->price_to_precision($symbol, $price);
            }
            $stopResponse = $this->privatePostV0MarketsSymbolStopOrders ($this->extend($stopRequest, $params));
            //
            //     {
            //         "to" => "0x1489eA81CBEDd53a8Eb1a95E99AF8EB5683b3330",
            //         "data" => "0x...",
            //         "value" => "100000000000000000",
            //         "chainId" => "50312"
            //     }
            //
            return $this->safe_order(array(
                'id' => null,
                'clientOrderId' => null,
                'timestamp' => null,
                'datetime' => null,
                'lastTradeTimestamp' => null,
                'status' => null,
                'symbol' => $market['symbol'],
                'type' => $type,
                'side' => $side,
                'price' => $price,
                'amount' => $amount,
                'filled' => null,
                'remaining' => null,
                'average' => null,
                'cost' => null,
                'triggerPrice' => $this->parse_number($triggerPrice),
                'trades' => null,
                'fee' => null,
                'info' => $stopResponse,
            ), $market);
        }
        $fundingSource = $this->safe_string($params, 'fundingSource');
        $selfMatchingOption = $this->safe_string($params, 'selfMatchingOption');
        $params = $this->omit($params, array( 'walletAddress', 'fundingSource', 'selfMatchingOption' ));
        $isMarketOrder = ($type === 'market');
        if (!$isMarketOrder && $price === null) {
            throw new ArgumentsRequired($this->id . ' createOrder() requires a $price argument for limit orders');
        }
        $postOnly = null;
        list($postOnly, $params) = $this->handle_post_only($isMarketOrder, false, $params);
        $timeInForce = $this->safe_string_upper($params, 'timeInForce');
        $params = $this->omit($params, 'timeInForce');
        $request = array(
            'symbol' => $market['id'],
            'walletAddress' => $walletAddress,
            'type' => $type,
            'side' => $side,
            'amount' => $this->amount_to_precision($symbol, $amount),
        );
        if (!$isMarketOrder) {
            $request['price'] = $this->price_to_precision($symbol, $price);
        }
        if ($postOnly) {
            $request['orderType'] = 'postOnly';
        } elseif ($timeInForce === 'IOC') {
            $request['orderType'] = 'immediateOrCancel';
        } elseif ($timeInForce === 'FOK') {
            $request['orderType'] = 'fillOrKill';
        }
        if ($fundingSource !== null) {
            $request['fundingSource'] = $fundingSource;
        }
        if ($selfMatchingOption !== null) {
            $request['selfMatchingOption'] = $selfMatchingOption;
        }
        $response = $this->privatePostV0MarketsSymbolOrders ($this->extend($request, $params));
        //
        //     {
        //         "chainId" => "50312",
        //         "data" => "0x80702f83...",
        //         "to" => "0xcee4c19f4518A10FBeF92390FE6d9e7B18A4070c",
        //         "value" => "0"
        //     }
        //
        return $this->safe_order(array(
            'id' => null,
            'clientOrderId' => null,
            'timestamp' => null,
            'datetime' => null,
            'lastTradeTimestamp' => null,
            'status' => null,
            'symbol' => $market['symbol'],
            'type' => $type,
            'side' => $side,
            'price' => $price,
            'amount' => $amount,
            'filled' => null,
            'remaining' => null,
            'average' => null,
            'cost' => null,
            'trades' => null,
            'fee' => null,
            'info' => $response,
        ), $market);
    }

    public function fetch_order(string $id, ?string $symbol = null, $params = array ()): array {
        /**
         * fetches information on an order made by the user
         *
         * @see https://api.dreamdex.io/v0/.well-known/oapi.json
         *
         * @param {string} $id the order $id
         * @param {string} $symbol unified $market $symbol, required for dreamdex
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} an ~@link https://docs.ccxt.com/#/?$id=order-structure order structure~
         */
        if ($symbol === null) {
            throw new ArgumentsRequired($this->id . ' fetchOrder() requires a $symbol argument');
        }
        $this->authenticate_rest();
        $this->load_markets();
        $market = $this->market($symbol);
        $request = array(
            'symbol' => $market['id'],
            'id' => $id,
        );
        $response = $this->privateGetV0MarketsSymbolOrdersId ($this->extend($request, $params));
        //
        //     {
        //         "id" => "01KC1F8N2NBP5GEYKE66CRJ34A",
        //         "status" => "open",
        //         "createdAt" => 1765534169841,
        //         "symbol" => "SOMI:USDso",
        //         "type" => "limit",
        //         "side" => "buy",
        //         "price" => "1.25",
        //         "amount" => "500",
        //         "filled" => "150",
        //         "remaining" => "350",
        //         "walletAddress" => "0x1234...",
        //         "txHash" => "0xabc..."
        //     }
        //
        return $this->parse_order($response, $market);
    }

    public function fetch_orders(?string $symbol = null, ?int $since = null, ?int $limit = null, $params = array ()): array {
        /**
         * fetches a list of $orders placed by the user
         *
         * @see https://api.dreamdex.io/v0/.well-known/oapi.json
         *
         * @param {string} [$symbol] unified $market $symbol; when omitted returns $orders across all markets
         * @param {int} [$since] timestamp in ms of the earliest order to retrieve
         * @param {int} [$limit] the maximum number of $orders to retrieve
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->status] order status to filter by => 'open', 'closed', 'canceled', 'expired', 'rejected' (or 'pending', 'triggered', 'canceled', 'failed' for $stop $orders)
         * @param {bool} [$params->stop] set to true to fetch $stop $orders instead of regular $orders (requires $symbol)
         * @param {bool} [$params->trigger] alias for $params->stop
         * @return {Order[]} a list of ~@link https://docs.ccxt.com/#/?id=order-structure order structures~
         */
        $this->authenticate_rest();
        $this->load_markets();
        $stop = $this->safe_bool_2($params, 'stop', 'trigger');
        if ($symbol === null) {
            if ($stop) {
                throw new ArgumentsRequired($this->id . ' fetchOrders() requires a $symbol argument for $stop orders');
            }
            $allResponse = $this->privateGetV0Orders ($params);
            $allOrders = $this->safe_list($allResponse, 'orders', array());
            return $this->parse_orders($allOrders, null, $since, $limit);
        }
        $market = $this->market($symbol);
        $request = array(
            'symbol' => $market['id'],
        );
        if ($stop) {
            $params = $this->omit($params, array( 'stop', 'trigger' ));
            $stopResponse = $this->privateGetV0MarketsSymbolStopOrders ($this->extend($request, $params));
            $stopOrders = $this->safe_list($stopResponse, 'stopOrders', array());
            return $this->parse_orders($stopOrders, $market, $since, $limit);
        }
        $response = $this->privateGetV0MarketsSymbolOrders ($this->extend($request, $params));
        $orders = $this->safe_list($response, 'orders', array());
        return $this->parse_orders($orders, $market, $since, $limit);
    }

    public function fetch_open_orders(?string $symbol = null, ?int $since = null, ?int $limit = null, $params = array ()): array {
        /**
         * fetches a list of open orders placed by the user
         *
         * @see https://api.dreamdex.io/v0/.well-known/oapi.json
         *
         * @param {string} [$symbol] unified market $symbol; when omitted returns open orders across all markets
         * @param {int} [$since] timestamp in ms of the earliest order to retrieve
         * @param {int} [$limit] the maximum number of orders to retrieve
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {bool} [$params->stop] set to true to fetch pending $stop orders (requires $symbol)
         * @param {bool} [$params->trigger] alias for $params->stop
         * @return {Order[]} a list of ~@link https://docs.ccxt.com/#/?id=order-structure order structures~
         */
        $stop = $this->safe_bool_2($params, 'stop', 'trigger');
        $request = array(
            'status' => $stop ? 'pending' : 'open',
        );
        return $this->fetch_orders($symbol, $since, $limit, $this->extend($request, $params));
    }

    public function cancel_order(string $id, ?string $symbol = null, $params = array ()) {
        /**
         * cancels an open order
         *
         * @see https://api.dreamdex.io/v0/.well-known/oapi.json
         *
         * @param {string} $id order $id
         * @param {string} $symbol unified $market $symbol, required for dreamdex
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {bool} [$params->stop] set to true to cancel a $stop order (returns unsigned EVM transaction)
         * @param {bool} [$params->trigger] alias for $params->stop
         * @return {array} an ~@link https://docs.ccxt.com/#/?$id=order-structure order structure~
         */
        if ($symbol === null) {
            throw new ArgumentsRequired($this->id . ' cancelOrder() requires a $symbol argument');
        }
        $this->authenticate_rest();
        $this->load_markets();
        $market = $this->market($symbol);
        $stop = $this->safe_bool_2($params, 'stop', 'trigger');
        $request = array(
            'symbol' => $market['id'],
            'id' => $id,
        );
        if ($stop) {
            $params = $this->omit($params, array( 'stop', 'trigger' ));
            $stopResponse = $this->privateDeleteV0MarketsSymbolStopOrdersId ($this->extend($request, $params));
            // $stop order cancel returns unsigned EVM transaction, not an order object
            return $this->safe_order(array(
                'id' => $id,
                'clientOrderId' => null,
                'timestamp' => null,
                'datetime' => null,
                'lastTradeTimestamp' => null,
                'status' => null,
                'symbol' => $market['symbol'],
                'type' => null,
                'side' => null,
                'price' => null,
                'amount' => null,
                'filled' => null,
                'remaining' => null,
                'average' => null,
                'cost' => null,
                'trades' => null,
                'fee' => null,
                'info' => $stopResponse,
            ), $market);
        }
        $response = $this->privateDeleteV0MarketsSymbolOrdersId ($this->extend($request, $params));
        return $this->parse_order($response, $market);
    }

    public function edit_order(string $id, string $symbol, string $type, string $side, ?float $amount = null, ?float $price = null, $params = array ()) {
        /**
         * reduces the remaining quantity of an open order (the only edit the API supports)
         *
         * @see https://api.dreamdex.io/v0/.well-known/oapi.json
         *
         * @param {string} $id order $id
         * @param {string} $symbol unified $market $symbol, required for dreamdex
         * @param {string} $type not used, kept for CCXT unified signature
         * @param {string} $side not used, kept for CCXT unified signature
         * @param {float} $amount the new remaining quantity (must be less than current remaining)
         * @param {float} [$price] not supported -- will throw if provided
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} an ~@link https://docs.ccxt.com/#/?$id=order-structure order structure~ with the unsigned EVM transaction in the info field
         */
        if ($symbol === null) {
            throw new ArgumentsRequired($this->id . ' editOrder() requires a $symbol argument');
        }
        if ($amount === null) {
            throw new ArgumentsRequired($this->id . ' editOrder() requires an $amount argument (newQuantityRemaining)');
        }
        if ($price !== null) {
            throw new NotSupported($this->id . ' editOrder() does not support changing $price, only reducing quantity');
        }
        $this->authenticate_rest();
        $this->load_markets();
        $market = $this->market($symbol);
        $request = array(
            'symbol' => $market['id'],
            'id' => $id,
            'newQuantityRemaining' => $this->amount_to_precision($symbol, $amount),
        );
        $response = $this->privatePatchV0MarketsSymbolOrdersIdReduce ($this->extend($request, $params));
        //
        //     {
        //         "to" => "0x914eDb19d187403F6e2b061CD92FF68CC795EA71",
        //         "data" => "0x...",
        //         "value" => "0",
        //         "chainId" => "50312"
        //     }
        //
        return $this->safe_order(array(
            'id' => $id,
            'clientOrderId' => null,
            'timestamp' => null,
            'datetime' => null,
            'lastTradeTimestamp' => null,
            'status' => null,
            'symbol' => $market['symbol'],
            'type' => $type,
            'side' => $side,
            'price' => null,
            'amount' => $amount,
            'filled' => null,
            'remaining' => $amount,
            'average' => null,
            'cost' => null,
            'trades' => null,
            'fee' => null,
            'info' => $response,
        ), $market);
    }

    public function parse_order(array $order, ?array $market = null): array {
        $rawTriggerPrice = $this->safe_string($order, 'triggerPrice');
        if ($rawTriggerPrice !== null) {
            return $this->parse_stop_order($order, $market);
        }
        //
        //     {
        //         "id" => "01KC1F8N2NBP5GEYKE66CRJ34A",
        //         "status" => "open",
        //         "createdAt" => 1765534169841,
        //         "symbol" => "SOMI:USDso",
        //         "type" => "limit",
        //         "side" => "buy",
        //         "price" => "1.25",
        //         "amount" => "500",
        //         "filled" => "150",
        //         "remaining" => "350",
        //         "walletAddress" => "0x1234...",
        //         "txHash" => "0xabc..."
        //     }
        //
        $marketId = $this->safe_string($order, 'symbol');
        $market = $this->safe_market($marketId, $market, ':');
        $timestamp = $this->safe_integer($order, 'createdAt');
        $price = $this->safe_number($order, 'price');
        return $this->safe_order(array(
            'id' => $this->safe_string($order, 'id'),
            'clientOrderId' => null,
            'timestamp' => $timestamp,
            'datetime' => $this->iso8601($timestamp),
            'lastTradeTimestamp' => null,
            'status' => $this->parse_order_status($this->safe_string($order, 'status')),
            'symbol' => $market['symbol'],
            'type' => $this->safe_string($order, 'type'),
            'side' => $this->safe_string($order, 'side'),
            'price' => $price,
            'amount' => $this->safe_number($order, 'amount'),
            'filled' => $this->safe_number($order, 'filled'),
            'remaining' => $this->safe_number($order, 'remaining'),
            'average' => $price,
            'cost' => null,
            'trades' => null,
            'fee' => null,
            'info' => $order,
        ), $market);
    }

    public function parse_order_status(?string $status) {
        $statuses = array(
            'open' => 'open',
            'closed' => 'closed',
            'canceled' => 'canceled',
            'expired' => 'expired',
            'rejected' => 'rejected',
        );
        return $this->safe_string($statuses, $status, $status);
    }

