    public function parse_stop_order_status(?string $status) {
        $statuses = array(
            'pending' => 'open',
            'triggered' => 'closed',
            'canceled' => 'canceled',
            'failed' => 'rejected',
        );
        return $this->safe_string($statuses, $status, $status);
    }

    public function hash_message($message) {
        $binaryMessage = $this->encode($message);
        $binaryMessageLength = $this->binary_length($binaryMessage);
        $x19 = $this->base16_to_binary('19');
        $newline = $this->base16_to_binary('0a');
        $prefix = $this->binary_concat($x19, $this->encode('Ethereum Signed Message:'), $newline, $this->encode($this->number_to_string($binaryMessageLength))); // eslint-disable-line quotes
        return '0x' . $this->hash($this->binary_concat($prefix, $binaryMessage), 'keccak', 'hex');
    }

    public function sign_hash($hash, $privateKey) {
        $this->check_required_credentials();
        $signature = $this->ecdsa(mb_substr($hash, -64), mb_substr($privateKey, -64), 'secp256k1', null);
        $r = $signature['r'];
        $s = $signature['s'];
        $v = $this->int_to_base16($this->sum(27, $signature['v']));
        return '0x' . str_pad($r, 64, '0', STR_PAD_LEFT) . str_pad($s, 64, '0', STR_PAD_LEFT) . $v;
    }

    public function authenticate_rest($params = array ()) {
        $cachedToken = $this->safe_string($this->options, 'authToken');
        $cachedExpires = $this->safe_integer($this->options, 'authTokenExpires');
        $now = $this->milliseconds();
        if (($cachedToken !== null) && ($cachedExpires !== null) && ($now < $cachedExpires)) {
            return $cachedToken;
        }
        $nonceResponse = $this->publicGetV0AuthNonce ($params);
        $nonce = $this->safe_string($nonceResponse, 'nonce');
        $issuedAt = $this->iso8601($now);
        $url = $this->safe_string($this->urls['api'], 'rest');
        $message = $url . ' wants you to sign in with your Ethereum account:' . "\n" . $this->walletAddress . "\n" . "\n" . 'Sign in to Somnia DEX' . "\n" . "\n" . 'URI => ' . $url . "\n" . 'Version => 1' . "\n" . 'Chain ID => 50312' . "\n" . 'Nonce => ' . $nonce . "\n" . 'Issued At => ' . $issuedAt; // eslint-disable-line quotes
        $hash = $this->hash_message($message);
        $sig = $this->sign_hash($hash, $this->privateKey);
        $loginRequest = array(
            'message' => $message,
            'signature' => $sig,
        );
        $loginResponse = $this->publicPostV0AuthLogin ($loginRequest);
        //
        //     array( "token" => "eyJhbGciOi...", "expiresAt" => 1765537769841 )
        //
        $token = $this->safe_string($loginResponse, 'token');
        $expiresAt = $this->safe_integer($loginResponse, 'expiresAt');
        $this->options['authToken'] = $token;
        $this->options['authTokenExpires'] = $expiresAt;
        return $token;
    }

    public function sign($path, $api = 'public', $method = 'GET', $params = array (), $headers = null, $body = null) {
        $url = $this->safe_string($this->urls['api'], 'rest') . '/' . $this->implode_params($path, $params);
        $query = $this->omit($params, $this->extract_params($path));
        if ($api === 'private') {
            $token = $this->safe_string($this->options, 'authToken');
            $headers = array(
                'Authorization' => 'Bearer ' . $token,
            );
            if (($method === 'POST') || ($method === 'PATCH')) {
                $headers['Content-Type'] = 'application/json';
                $body = $this->json($query);
            } else {
                if ($query) {
                    $url .= '?' . $this->urlencode($query);
                }
            }
        } else {
            if ($method === 'POST') {
                $headers = array(
                    'Content-Type' => 'application/json',
                );
                $body = $this->json($query);
            } else {
                if ($query) {
                    $url .= '?' . $this->urlencode($query);
                }
            }
        }
        return array( 'url' => $url, 'method' => $method, 'body' => $body, 'headers' => $headers );
    }

    public function handle_errors(int $httpCode, string $reason, string $url, string $method, array $headers, string $body, $response, $requestHeaders, $requestBody) {
        if ($response === null) {
            return null;
        }
        $errorName = $this->safe_string($response, 'name');
        if ($errorName !== null) {
            $feedback = $this->id . ' ' . $body;
            $this->throw_exactly_matched_exception($this->exceptions['exact'], $errorName, $feedback);
            $this->throw_broadly_matched_exception($this->exceptions['broad'], $body, $feedback);
            if ($httpCode >= 400) {
                throw new ExchangeError($feedback);
            }
        }
        return null;
    }
}
